import math

def solve():
    alpha = math.sqrt(2)
    def f(m, n):
        return m * math.ceil(n * alpha) - n * math.floor(m * alpha)

    def is_pretty(m, n, k):
        if m <= 0 or n <= 0:
            return False
        return f(m, n) == k

    def is_cool(m, n, k):
        if not is_pretty(m, n, k):
            return False

        # (m-n, n) is pretty if m-n > 0 and n > 0
        if m > n:
            if is_pretty(m - n, n, k):
                return False

        # (m, n-m) is pretty if n-m > 0 and m > 0
        if n > m:
            if is_pretty(m, n - m, k):
                return False

        return True

    results = {}
    for k in range(1, 11):
        cool_pairs = []
        # Search range for m, n. Let's try a reasonable range first.
        # Based on the problem, the number of cool pairs should be small.
        # f(m, n) = m*ceil(n*alpha) - n*floor(m*alpha) = k
        # m*ceil(n*alpha) - n*floor(m*alpha) = m(floor(n*alpha)+1) - n*floor(m*alpha)
        # = m*floor(n*alpha) - n*floor(m*alpha) + m = k
        # Let A = floor(n*alpha), B = floor(m*alpha)
        # mA - nB + m = k
        # Since A ~ n*alpha and B ~ m*alpha, mA - nB ~ 0.
        # So m ~ k. This suggests m is around k.
        # Let's check m, n up to 2*k + some margin.
        limit = k * 3
        for m in range(1, limit):
            for n in range(1, limit):
                if is_cool(m, n, k):
                    cool_pairs.append((m, n))
        results[k] = len(cool_pairs)
    return results

