def solve():
    k = 1
    alpha = math.sqrt(2)
    count = 0
    # Since m*a_n + n*b_m = k and a_n, b_m in (0, 1),
    # m must be less than k and n must be less than k.
    for m in range(1, k + 1):
        for n in range(1, k + 1):
            # a_n = 1 - {n*alpha}
            # b_m = {m*alpha}
            # We use high precision for alpha if needed, but sqrt(2) is okay.
            an = 1 - (n * alpha % 1)
            bm = (m * alpha % 1)

            # The equation is m*an + n*bm = k
            # Use a small epsilon for floating point comparison
            if abs(m * an + n * bm - k) < 1e-9:
                # It's a pretty pair. Now check if it's cool.
                is_cool = True

                # Check (m-n, n)
                if m > n:
                    m_prime = m - n
                    n_prime = n
                    an_prime = 1 - (n_prime * alpha % 1)
                    bm_prime = (m_prime * alpha % 1)
                    if abs(m_prime * an_prime + n_prime * bm_prime - k) < 1e-9:
                        is_cool = False

                # Check (m, n-m)
                if n > m:
                    m_prime = m
                    n_prime = n - m
                    an_prime = 1 - (n_prime * alpha % 1)
                    bm_prime = (m_prime * alpha % 1)
                    if abs(m_prime * an_prime + n_prime * bm_prime - k) < 1e-9:
                        is_cool = False

                if is_cool:
                    count += 1
    return count

